const body = $json.body || {};
if (!body.message && !body.symptoms) throw new Error('Message or symptoms is required');
return [{ json: { ...body, validated: true } }];

const rawMessage = String($json.message ?? $json.body?.message ?? '');
const rawSymptoms = String($json.symptoms ?? $json.body?.symptoms ?? '');
const normalizedText = `${rawMessage} ${rawSymptoms}`
  .trim()
  .toLowerCase()
  .replace(/\s+/g, ' ');

const emergencyPhrases = [
  'severe chest pain',
  'severe difficulty breathing',
  'unconscious',
  'severe bleeding'
];

const emergency = emergencyPhrases.some(phrase => normalizedText.includes(phrase));
return [{ json: { ...$json, normalized_text: normalizedText, emergency } }];

// Optional future node: call IBM watsonx using n8n credentials.
// event_logged represents the later database or audit-log step.
return [{json:{risk_level:'GENERAL WELLNESS GUIDANCE', guidance:'Demo response: provide safe, general educational wellness information only.', event_logged:true}}];
